async function run() {
  const items = $input.all();
  const fs = require('fs');

  const basePath = '/data';
  const trackingFile = `${basePath}/processed_ids.json`;

  if (!fs.existsSync(basePath)) {
    fs.mkdirSync(basePath, { recursive: true });
  }

  let processed = new Set();
  if (fs.existsSync(trackingFile)) {
    try {
      processed = new Set(JSON.parse(fs.readFileSync(trackingFile, 'utf8')));
    } catch {
      processed = new Set();
    }
  }

  const results = [];
  let skippedCount = 0;

  // FIX: Use explicit inputIndex to correctly map binary data
  // even when items are skipped mid-loop
  for (let i = 0; i < items.length; i++) {

    const item = items[i];
    const input = item.json;
    const binary = item.binary || {};
    const messageId = input.id;

    // -------- SKIP ALREADY PROCESSED --------
    if (!messageId || processed.has(messageId)) {
      skippedCount++;
      continue;
    }

    // -------- FIX: SKIP HOST'S OWN SENT EMAILS --------
    // Gmail labels INBOX only for received mail.
    // SENT label means the host sent this — skip it.
    const labelIds = input.labelIds || [];
    const isSent = labelIds.includes('SENT');
    const isInbox = labelIds.includes('INBOX');

    if (isSent || !isInbox) {
      // This email was sent by the host (your reply) — do not process.
      skippedCount++;
      processed.add(messageId); // Mark so we don't re-evaluate
      continue;
    }

    // -------- HEADERS SAFE --------
    let headers = [];

    if (Array.isArray(input.payload?.headers)) {
      headers = input.payload.headers;
    } else if (Array.isArray(input.headers)) {
      headers = input.headers;
    }

    const getHeader = (name) => {
      if (!Array.isArray(headers)) return '';
      const found = headers.find(h => h.name === name);
      return found ? found.value : '';
    };

    // -------- SUBJECT --------
    const subjectRaw =
      getHeader('Subject') ||
      input.subject ||
      'no-subject';

    const subject = subjectRaw
      .replace(/[^a-zA-Z0-9]/g, '_')
      .slice(0, 60);

    // -------- SENDER (FIXED) --------
    let senderEmail = 'unknown-sender';

    if (input.from?.value?.[0]?.address) {
      senderEmail = input.from.value[0].address;
    } else if (typeof input.from === 'string') {
      const match = input.from.match(/<(.+?)>/);
      senderEmail = match ? match[1] : input.from;
    } else {
      const fromHeader = getHeader('From');
      const match = fromHeader.match(/<(.+?)>/);
      senderEmail = match ? match[1] : fromHeader;
    }

    senderEmail = (senderEmail || 'unknown-sender')
      .trim()
      .toLowerCase();

    const safeSender = senderEmail.replace(/[<>:"/\\|?*]/g, '_');

    // -------- FOLDER CREATION (UNCHANGED — intentional logic kept as-is) --------
    let senderFolder = `${basePath}/${safeSender}`;
    let counter = 2;

    while (fs.existsSync(senderFolder)) {
      senderFolder = `${basePath}/${safeSender} (${counter})`;
      counter++;
    }

    fs.mkdirSync(senderFolder, { recursive: true });

    // -------- TIMESTAMP --------
    const timestamp = new Date()
      .toISOString()
      .replace(/[:.]/g, '-')
      .slice(0, 19);

    const folderPath = `${senderFolder}/${timestamp}_${subject}`;
    fs.mkdirSync(folderPath, { recursive: true });

    // -------- BODY EXTRACTION --------
    const decode = (data) => {
      try {
        return Buffer.from(data, 'base64url').toString('utf8');
      } catch {
        return '';
      }
    };

    const extractBody = (parts) => {
      let html = null;
      let text = null;

      for (const part of parts || []) {

        if (part.mimeType === 'text/html' && part.body?.data) {
          html = decode(part.body.data);
        }

        if (part.mimeType === 'text/plain' && part.body?.data) {
          text = decode(part.body.data);
        }

        if (part.parts) {
          const res = extractBody(part.parts);
          if (res.html) html = res.html;
          if (res.text) text = res.text;
        }
      }

      return { html, text };
    };

    const bodyParts = extractBody(input.payload?.parts);

    const emailBody =
      bodyParts.html ||
      bodyParts.text ||
      input.snippet ||
      input.text ||
      input.html ||
      'no body';

    // -------- WRITE EMAIL FILE --------
    const content = [
      `From: ${senderEmail}`,
      `Subject: ${subjectRaw}`,
      `Date: ${getHeader('Date') || ''}`,
      '',
      '----------------------------------------',
      '',
      emailBody
    ].join('\n');

    fs.writeFileSync(`${folderPath}/email.txt`, content, 'utf8');

    // -------- ATTACHMENTS (FIXED — full size, no truncation) --------
    let attachmentCount = 0;

    for (const [key, file] of Object.entries(binary)) {
      if (!key.startsWith('attachment_')) continue;

      try {
        const fileName = (file.fileName || file.name || `${key}.bin`)
          .replace(/[<>:"/\\|?*]/g, '_');

        const filePath = `${folderPath}/${fileName}`;

        let buffer;

        // FIX: Primary — use getBinaryDataBuffer with correct item index (i).
        // This reads from n8n's separate binary store and returns the FULL
        // untruncated file regardless of size.
        try {
          buffer = await this.helpers.getBinaryDataBuffer(i, key);
        } catch (bufErr) {
          // FIX: Fallback — if binary store read fails, decode from inline
          // base64 data (used for small attachments that Gmail embeds directly).
          if (file.data) {
            buffer = Buffer.from(file.data, 'base64');
          } else {
            throw new Error(`No binary data available for ${key}: ${bufErr.message}`);
          }
        }

        // FIX: Guard against empty/corrupt buffers — log and skip.
        if (!buffer || buffer.length === 0) {
          console.log(`[WARN] Empty buffer for attachment '${key}' in message ${messageId}. Skipping.`);
          continue;
        }

        // FIX: Log size so you can verify against the original in email client.
        console.log(`[OK] Saving '${fileName}' — size: ${buffer.length} bytes`);

        fs.writeFileSync(filePath, buffer);
        attachmentCount++;

      } catch (err) {
        console.log(`[ERROR] Attachment error (${key}):`, err.message);
      }
    }

    processed.add(messageId);

    results.push({
      json: {
        senderEmail,
        subject: subjectRaw,
        folderPath,
        attachmentsSaved: attachmentCount
      }
    });
  }

  fs.writeFileSync(
    trackingFile,
    JSON.stringify([...processed].slice(-1000))
  );

  if (results.length === 0) {
    return [{
      json: {
        status: "no_new_emails",
        skipped: skippedCount
      }
    }];
  }

  return results;
}

return run();
